func applyFrozenMainSchemaV2(database schemaExecutor) error {
	for _, object := range mainSchemaV2Objects {
		statement := frozenCreateIfNotExists(object.objectType, object.statement)
		if err := database.Exec(statement).Error; err != nil {
			return fmt.Errorf("apply frozen V2 %s %s: %w", object.objectType, object.name, err)
		}
	}
	return nil
}

func frozenCreateIfNotExists(objectType, statement string) string {
	switch objectType {
	case "table":
		return strings.Replace(statement, "CREATE TABLE ", "CREATE TABLE IF NOT EXISTS ", 1)
	case "index":
		if strings.HasPrefix(statement, "CREATE UNIQUE INDEX ") {
			return strings.Replace(statement, "CREATE UNIQUE INDEX ", "CREATE UNIQUE INDEX IF NOT EXISTS ", 1)
		}
		return strings.Replace(statement, "CREATE INDEX ", "CREATE INDEX IF NOT EXISTS ", 1)
	case "trigger":
		return strings.Replace(statement, "CREATE TRIGGER ", "CREATE TRIGGER IF NOT EXISTS ", 1)
	default:
		return statement
	}
}
